1	package events
2	
3	import (
4		"errors"
5		"strconv"
6		"strings"
7		"sync"
8		"sync/atomic"
9		"testing"
10		"time"
11	)
12	
13	func mkEvent(id, service, severity, message string, at time.Time) Event {
14		return Event{ID: id, Service: service, Severity: severity, Message: message, At: at}
15	}
16	
17	func TestIngestCreatesAndReplays(t *testing.T) {
18		tl := NewTimeline()
19		base := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
20		batch := []Event{
21			mkEvent("evt-2", "checkout", " WARN ", " latency ", base.Add(time.Minute)),
22			mkEvent("evt-1", "gateway", "CRITICAL", "spike", base),
23		}
24		var persisted []Event
25		res, err := tl.Ingest(batch, func(created []Event) error {
26			persisted = append(persisted, created...)
27			return nil
28		})
29		if err != nil {
30			t.Fatalf("ingest: %v", err)
31		}
32		if res.Created != 2 || res.Replayed != 0 {
33			t.Fatalf("unexpected result: %+v", res)
34		}
35		if len(persisted) != 2 {
36			t.Fatalf("commit hook got %d events", len(persisted))
37		}
38		if persisted[0].Severity != "warn" || persisted[0].Service != "checkout" {
39			t.Fatalf("normalization not applied before commit: %+v", persisted[0])
40		}
41	
42		// Identical retry, even with different formatting, is fully replayed.
43		retry := []Event{
44			mkEvent("  evt-1  ", "gateway", "critical", "spike", base),
45			mkEvent("evt-2", " checkout ", "warn", "latency", base.Add(time.Minute)),
46		}
47		res, err = tl.Ingest(retry, func(created []Event) error {
48			t.Fatalf("nothing should be persisted on replay, got %v", created)
49			return nil
50		})
51		if err != nil {
52			t.Fatalf("replay: %v", err)
53		}
54		if res.Created != 0 || res.Replayed != 2 {
55			t.Fatalf("unexpected replay result: %+v", res)
56		}
57	
58		all := tl.Query(Query{})
59		if len(all) != 2 || all[0].ID != "evt-1" || all[1].ID != "evt-2" {
60			t.Fatalf("timeline not ordered by time then id: %+v", all)
61		}
62	}
63	
64	func TestIngestAbsoluteTimeEquality(t *testing.T) {
65		tl := NewTimeline()
66		at := time.Date(2026, 10, 1, 10, 0, 0, 0, time.UTC)
67		sameInstant := at.In(time.FixedZone("CST", 8*60*60))
68		if !at.Equal(sameInstant) {
69			t.Fatal("test setup: instants differ")
70		}
71		if _, err := tl.Ingest([]Event{mkEvent("e", "s", "info", "m", at)}, nil); err != nil {
72			t.Fatalf("ingest: %v", err)
73		}
74		res, err := tl.Ingest([]Event{mkEvent("e", "s", "info", "m", sameInstant)}, nil)
75		if err != nil {
76			t.Fatalf("same instant in another zone should replay: %v", err)
77		}
78		if res.Replayed != 1 {
79			t.Fatalf("want replay, got %+v", res)
80		}
81	
82		other := sameInstant.Add(time.Nanosecond)
83		_, err = tl.Ingest([]Event{mkEvent("e", "s", "info", "m", other)}, nil)
84		if !IsConflictError(err) {
85			t.Fatalf("different instant should conflict, got %v", err)
86		}
87	}
88	
89	func TestIngestValidationPrecedesConflicts(t *testing.T) {
90		tl := NewTimeline()
91		base := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
92		_, err := tl.Ingest([]Event{mkEvent("dup", "s", "info", "old", base)}, nil)
93		if err != nil {
94			t.Fatalf("seed: %v", err)
95		}
96	
97		called := false
98		commit := func(created []Event) error { called = true; return nil }
99	
100		// Conflict present, but an invalid event comes first: validation wins.
101		batch := []Event{
102			mkEvent("dup", "s", "info", "different", base),
103			mkEvent("bad", "s", "info", "   ", base),
104		}
105		_, err = tl.Ingest(batch, commit)
106		if !IsValidationError(err) {
107			t.Fatalf("want validation error, got %v", err)
108		}
109		if called {
110			t.Fatal("commit hook must not run on validation failure")
111		}
112	
113		// Pure conflict once the batch is valid.
114		_, err = tl.Ingest([]Event{mkEvent("dup", "s", "info", "different", base)}, commit)
115		if !IsConflictError(err) {
116			t.Fatalf("want conflict error, got %v", err)
117		}
118		if called {
119			t.Fatal("commit hook must not run on conflict")
120		}
121		if got := tl.Query(Query{}); len(got) != 1 || got[0].Message != "old" {
122			t.Fatalf("rejected batch changed data: %+v", got)
123		}
124	}
125	
126	func TestIngestRejectsDuplicateIDWithinBatch(t *testing.T) {
127		tl := NewTimeline()
128		base := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
129		cases := [][]Event{
130			{mkEvent("a", "s", "info", "one", base), mkEvent("a", "s", "info", "one", base)},
131			{mkEvent(" a ", "s", "info", "one", base), mkEvent("a", "s2", "info", "two", base)},
132		}
133		for i, batch := range cases {
134			if _, err := tl.Ingest(batch, nil); !IsConflictError(err) {
135				t.Fatalf("case %d: want conflict, got %v", i, err)
136			}
137		}
138		if got := tl.Query(Query{}); len(got) != 0 {
139			t.Fatalf("rejected batches must not store anything: %+v", got)
140		}
141	}
142	
143	func TestIngestCommitFailureRejectsBatch(t *testing.T) {
144		tl := NewTimeline()
145		base := time.Now()
146		want := errors.New("disk gone")
147		_, err := tl.Ingest([]Event{mkEvent("e", "s", "info", "m", base)}, func(created []Event) error {
