	status, out = page(t, server, "?limit=3&cursor="+cursor)
	events, cursor = pageEvents(t, out)
	if len(events) != 3 || events[0]["id"] != "e2" || events[1]["id"] != "e3" || events[2]["id"] != "e4" {
		t.Fatalf("page 2 with changed limit: %v", events)
	}
